#!/usr/bin/env node
const { execFileSync } = require('child_process');
const fs = require('fs');

const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/numeric.jsonl';

const D3 = 'http://json-schema.org/draft-03/schema#';
const D4 = 'http://json-schema.org/draft-04/schema#';
const D6 = 'http://json-schema.org/draft-06/schema#';
const D7 = 'http://json-schema.org/draft-07/schema#';
const D19 = 'https://json-schema.org/draft/2019-09/schema';
const D20 = 'https://json-schema.org/draft/2020-12/schema';
const ALL = [D3, D4, D6, D7, D19, D20];

const pairs = [];
function add(a, b) { pairs.push([a, b]); }
// add across all drafts + a no-$schema variant
function sweep(a, bodyObj, drafts = ALL, alsoBare = true) {
  if (alsoBare) add(a, JSON.stringify(bodyObj));
  for (const s of drafts) add(a, JSON.stringify(Object.assign({ $schema: s }, bodyObj)));
}

/* ---------------- multipleOf: basics ---------------- */
sweep('10', { multipleOf: 3 });
sweep('9', { multipleOf: 3 });
sweep('10.0', { multipleOf: 3 });
sweep('9.0', { multipleOf: 3 });
sweep('0', { multipleOf: 3 });
sweep(' -0', { multipleOf: 3 });
sweep('0.0', { multipleOf: 3 });
sweep(' -0.0', { multipleOf: 3 });

/* multipleOf: non-number instances must be ignored */
sweep('true', { multipleOf: 3 });
sweep('false', { multipleOf: 3 });
sweep('"abc"', { multipleOf: 3 });
sweep('null', { multipleOf: 3 });
sweep('[]', { multipleOf: 3 });
sweep('{}', { multipleOf: 3 });
add('true', '{"multipleOf": 2}');
add('false', '{"multipleOf": 2}');

/* multipleOf: floats & precision */
add('4.5', '{"multipleOf": 1.5}');
add('0.0075', '{"multipleOf": 0.0001}');
add('0.00751', '{"multipleOf": 0.0001}');
add('1', '{"multipleOf": 0.0001}');
add('0.3', '{"multipleOf": 0.1}');
add('1.1', '{"multipleOf": 0.1}');
add('4.5', '{"multipleOf": 0.1}');
add('3.3', '{"multipleOf": 1.1}');
add('2.4', '{"multipleOf": 0.8}');
add('7', '{"multipleOf": 3.5}');
add('7.5', '{"multipleOf": 2.5}');
add('1', '{"multipleOf": 0.5}');
add('1', '{"multipleOf": 0.3}');
add('0.0001', '{"multipleOf": 0.0001}');
add('4.5', '{"multipleOf": 1.5000000000000002}');

/* multipleOf: huge / overflow */
add('1e308', '{"multipleOf": 1e-308}');
add('1e308', '{"multipleOf": 2}');
add('1e308', '{"multipleOf": 3}');
add('1e308', '{"multipleOf": 1.0}');
add('1e308', '{"multipleOf": 0.5}');
add('1e400', '{"multipleOf": 2}');
add('1e400', '{"multipleOf": 2.0}');
add('123456789012345678901234567890', '{"multipleOf": 3}');
add('123456789012345678901234567890', '{"multipleOf": 1.5}');
add('123456789012345678901234567890', '{"multipleOf": 7}');
add('1e-320', '{"multipleOf": 1e-320}');

/* multipleOf: negative / zero / bad types */
add('10', '{"multipleOf": -5}');
add('10', '{"multipleOf": -3}');
add('10', '{"multipleOf": -4}');
add('10.0', '{"multipleOf": -2.5}');
add('10', '{"multipleOf": 0}');
add('10', '{"multipleOf": 0.0}');
add('10', '{"multipleOf": -0.0}');
add('"x"', '{"multipleOf": 0}');
add('true', '{"multipleOf": 0}');
add('5', '{"multipleOf": true}');
add('5', '{"multipleOf": false}');
add('5', '{"multipleOf": null}');
add('5', '{"multipleOf": "3"}');
add('5', '{"multipleOf": [3]}');
sweep('5', { multipleOf: '3' });
sweep('5', { multipleOf: null });
sweep('5', { multipleOf: true });

/* ---------------- divisibleBy (draft3 keyword) ---------------- */
sweep('10', { divisibleBy: 3 });
sweep('9', { divisibleBy: 3 });
sweep('10', { divisibleBy: 0 });
sweep('10', { divisibleBy: 2.5 });
sweep('true', { divisibleBy: 3 });
add('10', JSON.stringify({ $schema: D3, divisibleBy: 3, multipleOf: 4 }));
add('10', JSON.stringify({ $schema: D4, divisibleBy: 3, multipleOf: 4 }));
add('0.0075', JSON.stringify({ $schema: D3, divisibleBy: 0.0001 }));

/* ---------------- maximum / minimum ---------------- */
sweep('5', { maximum: 3 });
sweep('5', { maximum: 5 });
sweep('5', { maximum: 7 });
sweep('5', { minimum: 7 });
sweep('5', { minimum: 5 });
sweep('5', { minimum: 3 });
sweep('5', { minimum: 10, maximum: 3 });
sweep('5', { minimum: 10, maximum: 3, multipleOf: 3 });
sweep('5', { minimum: 10, maximum: 3, divisibleBy: 3 });
sweep('true', { minimum: 10, maximum: 3 });
sweep('false', { minimum: 10, maximum: 3 });
sweep('"5"', { minimum: 10, maximum: 3 });
sweep('null', { maximum: 3 });
sweep('5.5', { maximum: 5 });
sweep(' -5', { minimum: 0 });
sweep(' -0.0', { minimum: 0 });
sweep(' -0.0', { maximum: 0 });

/* maximum/minimum bad value types */
sweep('5', { maximum: '3' });
sweep('5', { maximum: null });
sweep('5', { maximum: true });
sweep('5', { minimum: true });
add('0.5', '{"minimum": true}');
add('0.5', '{"maximum": true}');
add('5', '{"maximum": [3]}');

/* ---------------- exclusiveMaximum / exclusiveMinimum ---------------- */
/* bare numeric form */
sweep('5', { exclusiveMaximum: 5 });
sweep('5', { exclusiveMaximum: 6 });
sweep('5', { exclusiveMaximum: 4 });
sweep('5', { exclusiveMinimum: 5 });
sweep('5', { exclusiveMinimum: 4 });
sweep('5', { exclusiveMinimum: 6 });
sweep('5', { exclusiveMinimum: 6, exclusiveMaximum: 4 });

/* boolean modifier form (draft3/4 semantics) */
sweep('5', { maximum: 5, exclusiveMaximum: true });
sweep('5', { maximum: 5, exclusiveMaximum: false });
sweep('5', { maximum: 6, exclusiveMaximum: true });
sweep('5', { minimum: 5, exclusiveMinimum: true });
sweep('5', { minimum: 5, exclusiveMinimum: false });
sweep('5', { minimum: 4, exclusiveMinimum: true });
sweep('5', { maximum: 5, minimum: 5, exclusiveMaximum: true, exclusiveMinimum: true });

/* wrong-form crossovers */
sweep('5', { maximum: 10, exclusiveMaximum: 3 });   // numeric eM in d3/d4 = truthy flag
sweep('5', { maximum: 3, exclusiveMaximum: 10 });
sweep('5', { minimum: 1, exclusiveMinimum: 10 });
sweep('5', { minimum: 10, exclusiveMinimum: 1 });
sweep('5', { maximum: 3, exclusiveMaximum: 0 });    // 0 falsy in d3/d4
sweep('5', { minimum: 7, exclusiveMinimum: 0 });
sweep('5', { exclusiveMaximum: true });             // bare boolean, no maximum
sweep('5', { exclusiveMaximum: false });
sweep('5', { exclusiveMinimum: true });
sweep('5', { exclusiveMinimum: false });
sweep('0', { exclusiveMaximum: false });
sweep('0', { exclusiveMinimum: false });
sweep('0', { exclusiveMaximum: true });
sweep('0', { exclusiveMinimum: true });
sweep('2', { exclusiveMaximum: true });
sweep('5', { exclusiveMaximum: '3' });
sweep('5', { exclusiveMinimum: '3' });
sweep('5', { exclusiveMaximum: null });
/* key-order dependent crash site */
add('5', JSON.stringify({ $schema: D7, maximum: 3, exclusiveMaximum: 'no' }));
add('5', JSON.stringify({ $schema: D7, exclusiveMaximum: 'no', maximum: 3 }));
add('5', JSON.stringify({ $schema: D4, maximum: 3, exclusiveMaximum: 'no' }));

/* ---------------- combined / interaction with type ---------------- */
sweep('5', { type: 'integer', multipleOf: 2 });
sweep('5.0', { type: 'integer', multipleOf: 2 });
sweep('5.5', { type: 'integer', multipleOf: 2 });
sweep('5.5', { type: 'integer', maximum: 1 });
sweep('true', { type: 'number', maximum: 1 });
sweep('5', { type: 'number', maximum: 1, minimum: 9, multipleOf: 4 });

/* ---------------- nesting / error-count bubbling ---------------- */
add('{"a":5,"b":7}', '{"properties":{"a":{"maximum":1},"b":{"maximum":1}}}');
add('{"a":5}', '{"properties":{"a":{"maximum":1,"minimum":10}}}');
add('[5,7]', '{"items":{"maximum":1}}');
add('[5,7]', '{"prefixItems":[{"maximum":1},{"maximum":1}]}');
add('[5,7]', JSON.stringify({ $schema: D7, items: { maximum: 1 } }));
add('5', '{"anyOf":[{"maximum":1},{"minimum":10}]}');
add('5', '{"oneOf":[{"maximum":1},{"minimum":10}]}');
add('5', '{"allOf":[{"maximum":1},{"minimum":10}]}');
add('5', '{"allOf":[{"maximum":1,"minimum":10}]}');
add('5', '{"not":{"maximum":10}}');
add('5', '{"if":{"maximum":10},"then":{"minimum":100}}');
add('{"a":5}', '{"properties":{"a":{"multipleOf":0}}}');
add('[1,2,3]', '{"items":{"minimum":10,"maximum":0}}');

/* ---------------- misc numeric edges ---------------- */
add('1e400', '{"maximum":5}');
add('1e400', '{"minimum":5}');
add('1e400', '{"exclusiveMaximum":5}');
add('1e-400', '{"exclusiveMinimum":0}');
add('1e-400', '{"minimum":0}');
add('9007199254740993', '{"maximum":9007199254740992}');
add('9007199254740993', '{"multipleOf":1}');
add('5', '{"maximum":5.000000000000001}');
add('5', '{"exclusiveMaximum":5.000000000000001}');
add('0.1', '{"minimum":0.1,"exclusiveMinimum":0.1}');
sweep('9007199254740993', { maximum: 9007199254740992 }, ALL, false);

const lines = [];
let n = 0;
for (const [a, b] of pairs) {
  let out = '', code = 0;
  try {
    out = execFileSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
  } catch (e) {
    out = e.stdout == null ? '' : e.stdout.toString();
    code = typeof e.status === 'number' ? e.status : -1;
  }
  lines.push(JSON.stringify({ a, b, out, exit: code }));
  n++;
}
fs.writeFileSync(OUT, lines.join('\n') + '\n');
console.log('vectors:', n);

